  [("propósito explícito", "fin que el texto declara abiertamente"), ("propósito implícito", "fin que el texto persigue sin decirlo y que se infiere de pistas"), ("reportaje", "texto que investiga un tema en profundidad con varias fuentes"), ("pista textual", "palabra o recurso del texto que respalda una inferencia"), ("imagen institucional", "idea que el público se forma de una organización")],
