  ([E("¿Cuál es un criterio de evaluación de textos de los medios? (a) Suficiencia de información. (b) Si el texto me cae bien. (c) Si el texto es largo.", "(a)", "Es uno de los criterios del análisis de medios."),
    E("¿Qué debe acompañar a un juicio sobre un texto?", "Una cita o un dato del texto", "La evidencia respalda el juicio."),
    E("¿Qué parte de la evaluación indica la fuente del texto evaluado?", "La referencia", "Permite que otros lo encuentren.")],
   [E("Un estudiante escribe: «La nota no explica por qué subió el precio; falta la causa». ¿Qué criterio usa?", "Suficiencia de información", "Señala un dato que falta."),
    E("Otro escribe: «La nota dice que “los jóvenes son irresponsables”, y generaliza». ¿Qué criterio usa?", "Presencia de estereotipos y prejuicios", "Detecta una generalización sobre un grupo."),
    E("¿Cuál conclusión es más útil? (a) «Es un texto horrible.» (b) «Conviene leerlo con cuidado porque mezcla opiniones y datos; buscaría otra fuente.» (c) «No me interesa.»", "(b)", "Resume el análisis y recomienda una acción.")],
   [E("Evalúa con un criterio: «Titular: “Todos aprueban el cambio”. Texto: “Cuatro de seis directores lo apoyan”». Escribe tu juicio.", "Por ejemplo: el titular generaliza «todos» frente a cuatro de seis", "El juicio se apoya en la cifra del texto."),
    E("Ordena las partes de una evaluación: 1) conclusión y recomendación, 2) presentación del texto, 3) juicios por criterio. ¿Cuál es el orden?", "2, 3, 1", "Se presenta, se evalúa y se concluye."),
    E("¿Cuál referencia es adecuada? (a) «Diario del barrio, nota “Cierre de la plaza”, 12 de agosto.» (b) «Un diario.» (c) «Algo que leí.»", "(a)", "Indica medio, título y fecha.")],
   [E("Un compañero escribe en su evaluación: «El periodista quiso engañar». El texto no tiene pistas de engaño. ¿Qué corrección harías?", "Eliminar la intención o apoyarla con una pista; si no hay, decir solo qué datos faltan", "No se atribuye intención sin pista."),
    E("Antes de publicar, ¿qué revisarías en la cita «hubo 140 asistentes»? (a) Que coincida con el original. (b) Que esté en negrita. (c) Que esté en el centro.", "(a)", "Un dato mal copiado resta credibilidad.")],
   [E("Evaluación borrador: «El texto es parcial porque solo cita a la empresa; faltan los trabajadores, que son los afectados». ¿Qué criterio usa y qué evidencia?", "Criterio: comparación de fuentes o pluralidad de voces; evidencia: solo cita a la empresa", "Señala que falta una voz clave."),
    E("Para una audiencia de 6.º básico, ¿qué ajuste harías al escribir «propósito implícito»? (a) Explicar la expresión con un ejemplo breve. (b) Usarla sin explicarla. (c) Cambiarla por otra palabra difícil.", "(a)", "Se cuida que la audiencia comprenda los términos.")]),
  [E("Vas a publicar una evaluación en el diario mural. ¿Cuál es una buena presentación del texto evaluado? (a) «Nota del diario del barrio, del 8 de mayo, sobre el cierre de una calle.» (b) «Una nota rara.» (c) «Lo que vi en internet.»", "(a)", "Indica medio, fecha y tema.")],
